import subprocess

def get_memory_status():
    try:
        # 使用可能なメモリの取得
        result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', 'Get-CimInstance -Class Win32_PerfFormattedData_PerfOS_Memory | Select AvailableMBytes'], capture_output=True, text=True, check=True)
        available_memory = int(result.stdout.strip().split()[1])

        # 使用済みメモリの取得
        result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', 'Get-CimInstance -Class Win32_OperatingSystem | Select FreePhysicalMemory'], capture_output=True, text=True, check=True)
        free_memory = int(result.stdout.strip().split()[1])

        # 使用率の計算
        total_memory = available_memory + free_memory
        memory_usage = ((total_memory - available_memory) / total_memory) * 100

        return {'status': f'{memory_usage:.2f}%'}
    except subprocess.CalledProcessError as e:
        return {'status': '未実装'}

